inventory_movements_delta_sign.value:
(
    "inventory_movements"."movement_type" IN ('opening', 'receipt', 'transfer_in') AND "inventory_movements"."quantity_delta" > 0
  ) OR (
    "inventory_movements"."movement_type" IN ('sale', 'transfer_out') AND "inventory_movements"."quantity_delta" < 0
  ) OR "inventory_movements"."movement_type" = 'adjustment'

orders_fulfillment_details_valid.value:
(
    "orders"."fulfillment_method" = 'pickup' AND "orders"."delivery_details_snapshot" IS NULL AND "orders"."delivery_fee_clp" = 0
  ) OR (
    "orders"."fulfillment_method" = 'delivery' AND "orders"."delivery_details_snapshot" IS NOT NULL
    AND jsonb_typeof("orders"."delivery_details_snapshot") = 'object'
  )
